INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Need for Speed: V-Rally 2', 'Need for Speed: V-Rally 2 is a racing video game developed by Eden Studios and released in 1999, the second mainline entry in the V-Rally series. Similar to its predecessor, here, the player drive rally cars through a series of stages, with the game placing emphasis on replicating the behavior physics of real cars. The game includes various game modes, and can be played as single player, or up to four simultaneous players.' FROM games WHERE igdb_id = 6224 ON CONFLICT (game_id, language_code) DO NOTHING;
