INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Descent 3', 'The gut-wrenching Descent saga continues with more pulse-pounding action than ever before. Dive into massive subterranean strongholds and experience a whole new degree of freedom, as you careen through canyons and craters on the surface above... powered by the all-new Fusion engine. Test your piloting skills against an army of battle-drones and assault-bots using an extensive arsenal of tactics and heavy firepower.' FROM games WHERE igdb_id = 667 ON CONFLICT (game_id, language_code) DO NOTHING;
