INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingsley''s Adventure', 'Would you rather watch an adventure or be in one? This is the story of Kingsley, fox club and unlikely hero on a quest to save the Fruit Kingdom from the evil Wizard, Bad Custard. This is a job worthy only of a True Knight. Are you ready for the adventure of a lifetime?' FROM games WHERE igdb_id = 8308 ON CONFLICT (game_id, language_code) DO NOTHING;
