INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania', 'Take control of Reinhardt Schneider, a whip-toting Vampire Killer who has waited his whole life to meet his destiny, or Carrie Fernandez, a young girl with a strong magical presence who is mysteriously drawn to Dracula''s evil Castlevania. It is their duty to seek out Castlevania and put an end to its residents'' plans. What is your destiny?' FROM games WHERE igdb_id = 1130 ON CONFLICT (game_id, language_code) DO NOTHING;
