INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania: Legacy of Darkness', 'Castlevania: Legacy of Darkness is a video game that was developed and published by Konami for the Nintendo 64. It was first released in North America on November 30, 1999 and is a prequel and expanded version to the first Castlevania game on the Nintendo 64, but also contains a remake of the original game with improved graphics, added villains (Spider Queen, Medusa), and alternate versions of some levels (Forest of Silence, Tower of Science, Tower of Execution, Clock Tower).' FROM games WHERE igdb_id = 1131 ON CONFLICT (game_id, language_code) DO NOTHING;
