INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jagged Alliance 2', 'Jagged Alliance 2 is a perfect blend of strategy, roleplaying and tactical combat. With dozen of new weapons, 150+ individual in-game characters, realistic combat physics and more than 10,000 lines of digitalized speech. Welcome to the killing grounds!' FROM games WHERE igdb_id = 9 ON CONFLICT (game_id, language_code) DO NOTHING;
