INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('street-fighter-iii-3rd-strike', 6710, '1999-05-12', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6bkh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1p0x.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Fighter III: 3rd Strike', 'Street Fighter III: 3rd Strike is the second follow-up to Street Fighter III. The game increased the character roster by adding five new characters and also added further refinements to the previous game''s play mechanics and rules. All the returning characters from the previous Street Fighter III games were given new stages, endings, and voice actors for certain characters, continuing the overall storyline from where the first two games left off.' FROM games WHERE igdb_id = 6710 ON CONFLICT (game_id, language_code) DO NOTHING;
