INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alundra 2: A New Legend Begins', 'You are Flint, a renegade swordsman on a quest to free a kingdom from the grip of a sinister ruler. Through a land of hidden danger you wield your weapon, navigating an intricate story wrought with bizarre characters, brain-twisting puzzles and wild games. Beware! An even greater evil is about to be revealed...' FROM games WHERE igdb_id = 1176 ON CONFLICT (game_id, language_code) DO NOTHING;
