INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('panzer-front', 22008, '1999-12-22', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2chf.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panzer Front', 'Set in various theaters of World War II, this tank sim pits Russian, German, and American armor against each other in a series of missions designed to test both strategizing and twitching abilities, albeit with a heavy emphasis on the former. The game offers two main modes, Tank Select and Tactics. Tank Select is an arcade-style mode, with exaggerated tank capabilities and basic missions, most revolving around killing whatever moves. Tactics offers a selection of 28 different maps with a variety of terrain, opposition, and victory conditions. The missions are almost evenly divided between Russian, American, and German missions, but secondary factors mix things up so thoroughly that the different capabilities of each army''s tanks are only a small drop in the bucket full of strategic factors you have to consider.' FROM games WHERE igdb_id = 22008 ON CONFLICT (game_id, language_code) DO NOTHING;
