INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lode-runner-3-d', 3372, '1999-03-26', 62, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ql1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc74sj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lode Runner 3-D', 'The game mechanics are similar to the original; you outrun ''monsters'' by using alternate routes, sliding on ropes, climbing ladders or drilling holes in the ground to trap them. This game differs from the other incarnations of games from the series because of its apparent three-dimensional perspective. While essentially running in 2-dimensional space, the player has an option to move in another direction every so often. The levels are mostly spirals that require climbing to complete. There are five worlds and each one must be unlocked by finding five cards from the previous world excluding the first. Each world is divided into five stages with each stage divided into four levels. The general goal of each level is to collect a certain amount of gold to activate a portal that allows the player to continue. As the player progresses, each world adds new interactive objects and tools as well as new obstacles.' FROM games WHERE igdb_id = 3372 ON CONFLICT (game_id, language_code) DO NOTHING;
