INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pokemon-stadium', 2289, '1999-04-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yyd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21ya.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Stadium', 'In the game''s Stadium Mode, one player competes in 80 different battles, divided into four tournaments. Beat the Stadium Mode and you''re in for a bonus battle against the ultimate Pokémon warrior, Mewtwo, as well as a secret mode that gives you 80 brand-new, and devilishly tough battles. There is virtually no way you can beat the secret mode without having trained your own, elite Pokémon. One to four players compete against each other or the computer in a no-holds-barred battle with customizable rules. You can select rental Pokémon for these battles -- but that makes them much too predictable since their selection of techniques isn''t determined by the trainer. You can also select quick and easy versus and random battles.' FROM games WHERE igdb_id = 2289 ON CONFLICT (game_id, language_code) DO NOTHING;
