INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seaman', 'Seaman is a virtual pet video game for the Sega Dreamcast. It is one of the few Dreamcast games to take advantage of the microphone attachment. The narration is voiced by Toshiyuki Hosokawa in the original Japanese-language version and by Leonard Nimoy in the English-language version and the face of Seaman is actually that of the game''s producer, Yoot Saito.' FROM games WHERE igdb_id = 9130 ON CONFLICT (game_id, language_code) DO NOTHING;
