INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL Blitz 2000', 'It''s back and it''s better than ever! NFL Blitz 2000 adds 4-player support, new offensive and defensive plays, realistic weather conditions, new stadiums and a Tournament mode! Customize offensive and defensive plays to your liking. Call audibles at the line of scrimmage. You''ve got control now! Passing made easy with new "Blitz Passing" for one-touch long bombs! "ON-FIRE" mode gives super power performance to your players! With non-stop action and a "pick-it-up-and-play" learning curve, NFL BLITZ 2000 is THE game for every football fan!' FROM games WHERE igdb_id = 4366 ON CONFLICT (game_id, language_code) DO NOTHING;
