INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('guwange', 21162, '1999-06-24', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2eyf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5kcj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guwange', 'The story of Guwange is set during the Muromachi period of Japan. During this time, increasing numbers of people suffer possession by shikigami. Although the shikigami grant great spiritual powers, the strain inflicted on the host causes them to die exactly one year after possession. However, a legend has sprung up regarding Guwange, the malevolent god trapped in Mt. Gokumon (i.e. Hell Gate). If one possessed by a shikigami can gather talismans of the five Chinese elements—wood, fire, earth, metal, water—from five demons serving Guwange, then infiltrate Gokumon and slay Guwange, the shikigami will be destroyed and the one possessed will not suffer a premature death.' FROM games WHERE igdb_id = 21162 ON CONFLICT (game_id, language_code) DO NOTHING;
