INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Bros. Deluxe', 'Bowser has once again taken over the Mushroom Kingdom, and it''s up to Mario to put an end to his sinister reign. Battle Bowser''s vile henchmen through 32 different levels - all taken directly from the 1985 classic! Then move on to collect special Red Coins and Yoshi Eggs in the Challenge Mode. Or face off against a friend and race through 8 competition courses in the all-new VS Mode! This time there''s a lot more to do than just save a Princess, so get ready for a brick-smashin'', pipe-warpin'', turtle-stompin'' good time!' FROM games WHERE igdb_id = 49877 ON CONFLICT (game_id, language_code) DO NOTHING;
