INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spy Fox 2: "Some Assembly Required"', 'Once again, the world relies on Fox - Spy Fox, the suave secret agent who smoothly finesses his way through Spy Corps'' toughest assignments. This time, Spy Corps'' corrupt counterpart, the Society for Meaningless Evil, Larceny, Lying and Yelling (S.M.E.L.L.Y.) has devised a dogbot which will be unleashed upon the unsuspecting world! In his nastiness, S.M.E.L.L.Y.''s corrupt commander, Napoleon LeRoach, did not install an OFF switch on the dogbot. Instead, he hid the switch somewhere within the World''s Fair.' FROM games WHERE igdb_id = 16591 ON CONFLICT (game_id, language_code) DO NOTHING;
