INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BattleTanx: Global Assault', 'Global Assault is the sequel to the original BattleTanx. It features many new weapons, new vehicles, and new powers that were not available in the original. Global Assault now also features a destructible environment, allowing you to seize control of the environment and create ultimate destruction. Global Assault allows two players to play together in co-operative mode, or four players to go head-to-head as one of the dozens of tank gangs in all new maps and many more game modes.' FROM games WHERE igdb_id = 47685 ON CONFLICT (game_id, language_code) DO NOTHING;
