INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic the Hedgehog Pocket Adventure', 'Help Sonic rescue his forest friends from the evil Dr. Robotnik. Grab those golden rings and collect all the chaos emeralds for special bonuses. Rush through multiple bonus levels and challenge the high score record. Collect puzzle pieces and complete the mystery photo. Play against a friend in a 2-player Vs. battle. The action is gonna be super SONIC!' FROM games WHERE igdb_id = 43323 ON CONFLICT (game_id, language_code) DO NOTHING;
