INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Team Fortress Classic', 'One of the most popular online action games of all time, Team Fortress Classic features over nine character classes -- from Medic to Spy to Demolition Man -- enlisted in a unique style of online team warfare. Each character class possesses unique weapons, items, and abilities, as teams compete online in a variety of game play modes.' FROM games WHERE igdb_id = 6359 ON CONFLICT (game_id, language_code) DO NOTHING;
