INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chocobo Racing', 'The Chocobo has appeared in every Final Fantasy game since Final Fantasy IV as a large yellow bird that you can ride to other destinations or use during fights. With Chocobo Racing, you can race a Chocobo along with a range of different characters both from the Final Fantasy world including Cloud and Cid from Final Fantasy VII and created just for the game through many different fantasy worlds at high speed, using a selection of weapons to aid you. The game supports 1 and 2 player racing' FROM games WHERE igdb_id = 22896 ON CONFLICT (game_id, language_code) DO NOTHING;
