INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Myst: Masterpiece Edition', 'Myst: Masterpiece Edition is a remastered version of 1993''s Myst. This edition features improvements over the original release, such as re-rendered imagery in 24-bit color, a remastered score, and enhanced sound effects. In the game, players travel via a special book to the island of Myst. There, players solve puzzles, and by doing so, travel to four other worlds, known as Ages, which reveal the backstory of the game''s characters.' FROM games WHERE igdb_id = 16203 ON CONFLICT (game_id, language_code) DO NOTHING;
