INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Man World', 'Twenty years after Pac-Man''s first adventure in Pac-Land, Pac-Man returns one day to his house only to find it deserted. Toc-Man and his ghosts have kidnapped Pac-Man''s friends, Ms. Pac-Man, Pac Jr., Baby Pac, Professor Pac, Pooka, and Chomp-Chomp the dog! Pac-Man must venture to Toc-Man''s lair on Ghost Island to rescue his friends!
