INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ChuChu Rocket!', 'The object of the game is to guide one or more mice ("ChuChus") around a board into one or more goals while avoiding cats ("KapuKapus") roaming the board. The mice and cats all move in predictable paths by always turning right when hitting a wall head on, by following corners or by turning around when in a dead end.
