INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Party 2', 'Mario and the gang are back for another round of Bowser-bashin'' party action! Watch as your favorite Nintendo characters don different duds for each of the five all-new Adventure Boards! A slew of new tricks and devices bring new levels of challenge and excitement to board game play. New board maps, new Mini-Games, new action and new surprises means a whole new batch of fun! Get ready to unleash your best Hip Drops, hammer swings and high-flying high junks for another round of frenzied multi-player action!' FROM games WHERE igdb_id = 2328 ON CONFLICT (game_id, language_code) DO NOTHING;
