INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ncaa-final-four-99', 23154, '1999-02-13', 63, 'https://images.igdb.com/igdb/image/upload/t_cover_big/rhvt8yfbbyu8dzygwena.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NCAA Final Four 99', 'NCAA FINAL FOUR ''99 offers three gameplay modes: Exhibition, Tournament, and a 30-game Season. The rules can be configured to your preferences, whether it''s arcade or simulation. This affects which fouls get called and determines whether or not your players feel the effects of fatigue. You can also choose from a variety of controller configurations, difficulty settings, game lengths, and camera angles to alter the game. And of course, everything is rendered in 3D, which creates the feeling that you''re right in the middle of the action. There are 250 Division I teams available, making it easy to find your favorite squad on the roster. The sound, which includes play-by-play commentary, ball thumps, and sneaker squeaks, works well to get you pumped up and involved in the game. You can also play with up to eight friends (with a multitap) in the multiplayer game.' FROM games WHERE igdb_id = 23154 ON CONFLICT (game_id, language_code) DO NOTHING;
