INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'System Shock 2', 'A first-person cyberpunk exploratory horror RPG and sequel to System Shock (1994) in which a soldier wakes up in the starship Von Braun in the aftermath of a disaster and finds himself in the midst of a conflict between SHODAN, the artificial intelligence antagonist of System Shock seeking mastery over humanity, and The Many, a flesh-based psychic hive mind led by the ship''s corrupted AI.' FROM games WHERE igdb_id = 22 ON CONFLICT (game_id, language_code) DO NOTHING;
