INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TOCA 2: Touring Car Challenge', 'TOCA 2: Touring Car Challenge is a racing game developed and published by Codemasters in 1998. It is based on the British Touring Car Championship and features all official cars, drivers, and tracks from the 1998 season. The game offers multiple modes, including Championship, Single Race, and Time Trial. Improved physics, handling, and AI were introduced compared to its predecessor, TOCA Touring Car Championship.' FROM games WHERE igdb_id = 8001 ON CONFLICT (game_id, language_code) DO NOTHING;
