INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('galerians', 54552, '1999-08-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4py3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9h5p.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galerians', 'Galerians is a survival horror game in which the player navigates a 3D character model over pre-rendered backgrounds, using character-related controls similar to those implemented in Alone in the Dark. Items must be collected to unlock new areas and advance the story. Unlike in most other games of the type, the protagonist is unable to use weapons. Rion fully relies on his psychic powers to combat enemies. These powers must be replenished by regularly taking drugs. In addition, Rion has a special meter that throws him into uncontrollable rage when full.' FROM games WHERE igdb_id = 54552 ON CONFLICT (game_id, language_code) DO NOTHING;
