INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conker''s Pocket Tales', 'It''s Conker''s birthday and someone crashed his party! The Evil Acorn has stolen all of Conker''s presents and kidnapped his best chipmunk friend, Berri. Now you must take on the role of the bushy-tailed hero, pursuing your nemesis throughout 6 visually-stunning worlds to rescue Berri and save your birthday from complete disaster. Strain your brain to solve challenging puzzles, battle the Evil Acorn''s horde of minions with your trusty slingshot, and even flex your muscles in sporting events as you track your foe to the final showdown!' FROM games WHERE igdb_id = 1424 ON CONFLICT (game_id, language_code) DO NOTHING;
