INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SimCity 3000', 'SimCity 3000, released in 1999 as the third major installment in the SimCity series, continues its successful course as a city building simulation game. In SimCity 3000 new tools have been introduced to create and control the city build-ups. Recreate the world''s greatest cities using predefined landscapes such as San Francisco or Berlin and landmark buildings like the Empire State Building or Big Ben. Negotiate and barter with neighbouring cities to strengthen your metropolis and seal contracts to import water or get rid of huge amounts of waste.' FROM games WHERE igdb_id = 237 ON CONFLICT (game_id, language_code) DO NOTHING;
