INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vib-ribbon', 9676, '1999-12-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6xgh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8lbe.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vib-Ribbon', 'Vib-Ribbon is a rhythm game where the player must maneuver musically generated obstacles based on either the game''s own soundtrack or a music CD of the player''s choice. The player must avoid each obstacle by pressing the correct button at the right time - either L, R, X or down. In more complex tracks, obstacles are combined and the player must press the correct combination of buttons in order the avoid the obstacle. The game is loaded with six tracks to play by Japanese band Laugh and Peace. Additionally, the game''s unique software means that the game is loaded into the console''s RAM, allowing the player in insert their own music CDs, which generate a unique course for each track.' FROM games WHERE igdb_id = 9676 ON CONFLICT (game_id, language_code) DO NOTHING;
