INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Dragoon', 'The Legend of Dragoon is a Japanese-style RPG, visually reminiscent of Final Fantasy VII (pre-rendered backgrounds, 3D characters and battle scenes, CG animations to advance the story). Battle mechanics follow the traditional turn-based prototype, with a few additions such as critical attacks dependent on precise timing, and "dragoon" transformations, which allow access to powerful techniques. Game progression is largely linear, with the "world map" replaced by locations represented as connected dots.' FROM games WHERE igdb_id = 3140 ON CONFLICT (game_id, language_code) DO NOTHING;
