INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slave Zero', 'It''s 500 years in the future. Man and machine are virtually on and the greatest megacity in the world is locked in a brutal war. You are the ultimate saboteur and part of an elite fighting force. Your mission: steal the largest, most sophisticated bio-mechanical attack weapon ever designed ...and kick some serious ass!' FROM games WHERE igdb_id = 8341 ON CONFLICT (game_id, language_code) DO NOTHING;
