INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighting Force 2', 'Fighting Force 2 is the sequel to 1997''s original Fighting Force, which was one of the first 3D takes on the 2D Beat ''em up genre. The game was released for the PlayStation and Dreamcast and was developed by Core Design and published by Eidos Interactive. It was released in North America on 30 November 1999.' FROM games WHERE igdb_id = 11615 ON CONFLICT (game_id, language_code) DO NOTHING;
