INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hybrid Heaven', 'A gunshot echoes through the tunnels of the New York subway system. A secret service agent lies dying, and Diaz, with a gun gripped tightly in his hand, flees and stumbles into a strange underground world where a secret society of genetically engineered hybrid clones threaten to subvert the population of the outside world. Experience New York City''s secret night life in Hybrid Heaven, a unique, fully-immersive action RPG that combines fighting, action, and role playing into a story of alien invasion, scientific experimentation, and murder. Unravel the secrets of the hybrid society, the future of humanity, and the true identity of Diaz.' FROM games WHERE igdb_id = 3513 ON CONFLICT (game_id, language_code) DO NOTHING;
