INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Densha de GO! Professional', 'A train simulation game by Taito featuring the lines from Densha de Go! 1 and 2, as well as some Kantou area portions of the Toukaidou Line. Some of the strictness of the previous games was reduced through a number of features, including the addition of a panel at left which allowed the user to see a map of the upcoming track segment, including showing speed limits, which greatly reduced the required amount of track memorization, and allowed the player more time to react. The overall reduction of strictness in the game reflected Taito''s shift in emphasis from arcade to home-play versions as time went on.' FROM games WHERE igdb_id = 78575 ON CONFLICT (game_id, language_code) DO NOTHING;
