INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supreme Snowboarding', 'Supreme Snowboarding is the first snowboarding game that allows players to experience pure freedom, with the possibility to choose your very own way down the slopes. 10 race tracks, three half-pipes and three straight jumps offer something for everyone, from straight race maniacs to pipe-loving daredevils. Select a character, choose a board and hit the slopes, dude!
