INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Corsairs: Conquest at Sea', 'Corsairs: Conquest at Sea is a 1999 strategy/action/adventure game for the PC, developed and published by Microïds (known for Syberia and its continuation Syberia II). The game is a simulation of the life of a privateer employed by either England, France, The Netherlands or Spain in, most likely, the 17th century. The player can take part in either the campaign, which consists of several scenarios with a specific goal, or adventure mode, where the goal is simply to capture all the ports on the map for your nation.' FROM games WHERE igdb_id = 10107 ON CONFLICT (game_id, language_code) DO NOTHING;
