INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cendric''s Quest', 'Cendric''s Quest. a prequel to SerpentHead, tells the story of how the mage Cendric, brought the SerpentScepter back from Castle IronGate. Long ago, Cendric''s grandfather, the great Ophiuchus, hid the weapon in the abandoned fortress to keep it out of the hands of the Dark Sorcerer, Salorann. Now, Salorann is once again threatening the peace, and Cendric must recover the Scepter to win the day.' FROM games WHERE igdb_id = 118212 ON CONFLICT (game_id, language_code) DO NOTHING;
