INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Recoil', 'Recoil is a vehicular combat tank-based Microsoft Windows video game. It involves the player piloting an experimental tank known as the "BFT" (Battle Force Tank) through various missions. There is a heavy influence on collecting various weapons for the BFT throughout the game. It was developed by Zipper Interactive, a subsidiary of its parent publisher, Electronic Arts, and uses the same game engine as MechWarrior 3.' FROM games WHERE igdb_id = 117276 ON CONFLICT (game_id, language_code) DO NOTHING;
