INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nocturne', 'Nocturne is a survival horror adventure video game set in the late 1920s and early 1930s – the Prohibition and Great Depression era. The player takes the part of The Stranger an operative of a fictional American Government secret organization known as "Spookhouse", which was created by President Theodore Roosevelt to fight monsters. He investigates four strange cases and saves people from classic monsters such as werewolves, zombies, and vampires.' FROM games WHERE igdb_id = 4850 ON CONFLICT (game_id, language_code) DO NOTHING;
