INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Smurfs', 'This game is targeted to young players. This is a 3D lateral view platformer where the player controls one of those little blue people through 20 levels in order to save his friends captured by the evil Gargamel. Levels features forest, icy plains, volcano undergrounds, Gargamel''s castle, the Smurf''s village, and so on. The adventure itself is split in two parts, one being a simple tutorial while the second parts represents the game itself.' FROM games WHERE igdb_id = 106272 ON CONFLICT (game_id, language_code) DO NOTHING;
