INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Antz', 'Antz is a side-scrolling platformer based on the movie of the same name. You take the role of Z, and you set out to win the heart of Princess Bala. Each of the 19 levels is based on situations in the movie. Your character has a variety of actions: crouching down, going through tunnels, hiding from enemies, jumping over obstacles, hanging from trees, climbing ropes and more. You also encounter boss characters.' FROM games WHERE igdb_id = 94622 ON CONFLICT (game_id, language_code) DO NOTHING;
