INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crisis Zone', 'Crisis Zone is a light gun arcade game released by Namco in 1999, a spin-off of the Time Crisis series. As a feature, it handles a large machine gun type controller instead of a handgun like the conventional work. In 2004, the Playstation2 version was released with Guncon2 support.' FROM games WHERE igdb_id = 13896 ON CONFLICT (game_id, language_code) DO NOTHING;
