INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disciples: Sacred Lands', 'Disciples: Sacred Lands is a turn-based PC strategy game published by Strategy First in 1999. Set in a fantasy world known as the Sacred Lands, it depicts a battle for dominance between four races of the world of Nevendaar: The Empire (humans), the Mountain Clans (dwarves) the Legions of the Damned (demons), and the Undead Hordes (undead).' FROM games WHERE igdb_id = 6541 ON CONFLICT (game_id, language_code) DO NOTHING;
