INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tyrian 2000', 'Tyrian 2000 is an updated rerelease of the original Tyrian. Tyrian is an action killing, smashing, shoot''em''all arcade game. Your goal is to kill as many enemies as possible and finish the level, buy more weapons and then kill many more enemies. Your battle ship can be improved over time and you can buy new weapons currently available. Your ship supports front guns, rear guns and side slots for the most deadly weapons.' FROM games WHERE igdb_id = 14432 ON CONFLICT (game_id, language_code) DO NOTHING;
