INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Jam 2000', 'All-new 2-on-2 JAM mode featuring 50 dunks and awesome special effects! Custom 2-on-2 JAM mode courts, including street court. Authentic 5-on-5 simulation mode with actual team play styles like the Jazz Pick-and-Roll. Jaw-dropping ultra high-rez graphics! Unique signature moves like the crossover dribble. Create your own JAM player. All 29 teams and over 300 NBA superstars! Over 800 all-new motion captured moves by the "X-Man" Xavier McDaniel!' FROM games WHERE igdb_id = 3552 ON CONFLICT (game_id, language_code) DO NOTHING;
