INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Rash 64', '180 MPH slap in the face, anyone? Multi-player modes for up to four players including Deathmatch, Cop Mode and Tag. New weapons and moves like the dreaded spoke jam. Intense pack brawling, including grudges and alliances. 200 miles of interconnected tracks and environments. Over 25 bikes and characters to choose from. Thrashin'' soundtrack featuring Sugar Ray, The Mermen and more!' FROM games WHERE igdb_id = 3589 ON CONFLICT (game_id, language_code) DO NOTHING;
